// Написан вручную (несколько ролей — генератор не умеет), не проверен на живой странице — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md
// Геолокация эмулируется; Date Now не включается; в конце шаринг выключается у всех ролей.
import { test, expect } from '../../fixtures';
import { setupMapUser, enableSharing, disableSharing, openMap, fetchNearby, expectInNearby, userIdOf, rowId, GEO } from './map-helpers';
import { metersBetween } from './pair-helpers';

test.describe('מיקום ומפה בזמן אמת', () => {
  test.describe.configure({ timeout: 240_000 }); // две роли + ожидание опроса карты у другого (#0f19c0)
  test('nearby_live: виден только шарящий подходящий пользователь, примерные координаты, distance_m, date_now @iphone @data (#46db57 #2a31ff #f3fc59)', async ({ asUser }) => {
    const free = await asUser('free');
    const user4 = await asUser('user4');
    await setupMapUser(free, 'free');
    await setupMapUser(user4, 'user4');
    const freeId = userIdOf('free');
    const user4Id = userIdOf('user4');
    try {
      // user4 не шарит → её нет у free (AC 4 #46db57, AC 9 #2a31ff).
      await disableSharing(user4);
      await enableSharing(free);
      await expectInNearby(free, user4Id, false);

      // user4 включает шаринг → появляется у free (AC 1–2 #2a31ff, AC 2 #46db57).
      await enableSharing(user4);
      await expectInNearby(free, user4Id, true);
      const row = (await fetchNearby(free)).find((r) => rowId(r) === user4Id)!;
      // Координаты — ПРИМЕРНЫЕ (решение клиента 10.11, #f3fc59 «עבר QA» 11.11; заменяет «точные» из AC 3 #46db57):
      // не больше 4 знаков после точки и в окрестности эмулированной точки (до ~700 м, запас 100 м).
      expect((String(row.lat).split('.')[1] ?? '').length).toBeLessThanOrEqual(4);
      expect((String(row.lng).split('.')[1] ?? '').length).toBeLessThanOrEqual(4);
      expect(metersBetween({ lat: Number(row.lat), lng: Number(row.lng) }, { lat: GEO.user4.latitude, lng: GEO.user4.longitude })).toBeLessThanOrEqual(800);
      expect(typeof row.distance_m).toBe('number');
      expect(Number(row.distance_m)).toBeGreaterThan(0);
      expect(Number(row.distance_m)).toBeLessThan(1000);
      // Пометка Date Now есть в ответе (AC 5 #46db57); режим не включаем — проверяем только наличие флага.
      expect(row).toHaveProperty('date_now');
      expect(typeof row.date_now).toBe('boolean');
      // Взаимно: user4 видит free.
      await openMap(user4);
      await expectInNearby(user4, freeId, true);
    } finally {
      await disableSharing(free);
      await disableSharing(user4);
    }
  });
});
